28. object Neo4jUtil {
29. 
30.   val NODE_ALIAS = "n"
31.   private val INTERNAL_ID_FIELD_NAME = "id"
32.   val INTERNAL_ID_FIELD = s"<${INTERNAL_ID_FIELD_NAME}>"
33.   private val INTERNAL_LABELS_FIELD_NAME = "labels"
34.   val INTERNAL_LABELS_FIELD = s"<${INTERNAL_LABELS_FIELD_NAME}>"
35.   val INTERNAL_REL_ID_FIELD = s"<rel.${INTERNAL_ID_FIELD_NAME}>"
36.   val INTERNAL_REL_TYPE_FIELD = "<rel.type>"
37.   val RELATIONSHIP_SOURCE_ALIAS = "source"
38.   val RELATIONSHIP_TARGET_ALIAS = "target"
39.   val INTERNAL_REL_SOURCE_ID_FIELD = s"<${RELATIONSHIP_SOURCE_ALIAS}.${INTERNAL_ID_FIELD_NAME}>"
40.   val INTERNAL_REL_TARGET_ID_FIELD = s"<${RELATIONSHIP_TARGET_ALIAS}.${INTERNAL_ID_FIELD_NAME}>"
41.   val INTERNAL_REL_SOURCE_LABELS_FIELD = s"<${RELATIONSHIP_SOURCE_ALIAS}.${INTERNAL_LABELS_FIELD_NAME}>"
42.   val INTERNAL_REL_TARGET_LABELS_FIELD = s"<${RELATIONSHIP_TARGET_ALIAS}.${INTERNAL_LABELS_FIELD_NAME}>"
43.   val RELATIONSHIP_ALIAS = "rel"
44. 
45.   private val properties = new Properties()
46.   properties.load(Thread.currentThread().getContextClassLoader().getResourceAsStream("neo4j-spark-connector.properties"))
47. 
48.   def closeSafety(autoCloseable: AutoCloseable, logger: Logger = null): Unit = {
49.     try {
50.       autoCloseable match {
51.         case s: Session => if (s.isOpen) s.close()
52.         case t: Transaction => if (t.isOpen) t.close()
53.         case null => ()
54.         case _ => autoCloseable.close()
55.       }
56.     } catch {
57.       case t: Throwable => if (logger != null) logger
58.         .warn(s"Cannot close ${autoCloseable.getClass.getSimpleName} because of the following exception:", t)
59.     }
60.   }
61. 
62.   val mapper = new ObjectMapper()
63.   private val module = new SimpleModule("Neo4jApocSerializer")
64.   module.addSerializer(classOf[Path], new JsonSerializer[Path]() {
65.     override def serialize(path: Path,
66.                            jsonGenerator: JsonGenerator,
67.                            serializerProvider: SerializerProvider): Unit = jsonGenerator.writeString(path.toString)
68.   })
69.   module.addSerializer(classOf[Entity], new JsonSerializer[Entity]() {
70.     override def serialize(entity: Entity,
71.                            jsonGenerator: JsonGenerator,
72.                            serializerProvider: SerializerProvider): Unit = jsonGenerator.writeObject(entity.toMap)
73.   })
74.   mapper.registerModule(module)
75. 
76.   def convertFromNeo4j(value: Any, schema: DataType = null): Any = {
77.     if (schema != null && schema == DataTypes.StringType && value != null && !value.isInstanceOf[String]) {
78.       convertFromNeo4j(mapper.writeValueAsString(value), schema)
79.     } else {
80.       value match {
81.         case node: InternalNode => {
82.           val map = node.asMap()
83.           val structType = extractStructType(schema)
84.           val fields = structType
85.             .filter(field => field.name != Neo4jUtil.INTERNAL_ID_FIELD && field.name != Neo4jUtil.INTERNAL_LABELS_FIELD)
86.             .map(field => convertFromNeo4j(map.get(field.name), field.dataType))
87.           InternalRow.fromSeq(Seq(convertFromNeo4j(node.id()), convertFromNeo4j(node.labels())) ++ fields)
88.         }
89.         case rel: InternalRelationship => {
90.           val map = rel.asMap()
91.           val structType = extractStructType(schema)
92.           val fields = structType
93.             .filter(field => field.name != Neo4jUtil.INTERNAL_REL_ID_FIELD
94.               && field.name != Neo4jUtil.INTERNAL_REL_TYPE_FIELD
95.               && field.name != INTERNAL_REL_SOURCE_ID_FIELD
96.               && field.name != INTERNAL_REL_TARGET_ID_FIELD)
97.             .map(field => convertFromNeo4j(map.get(field.name), field.dataType))
98.           InternalRow.fromSeq(Seq(convertFromNeo4j(rel.id()),
99.             convertFromNeo4j(rel.`type`()),
100.             convertFromNeo4j(rel.startNodeId()),
101.             convertFromNeo4j(rel.endNodeId())) ++ fields)
102.         }
103.         case d: InternalIsoDuration => {
104.           val months = d.months()
105.           val days = d.days()
106.           val nanoseconds: Integer = d.nanoseconds()
107.           val seconds = d.seconds()
108.           InternalRow.fromSeq(Seq(UTF8String.fromString(SchemaService.DURATION_TYPE), months, days, seconds, nanoseconds, UTF8String.fromString(d.toString)))
109.         }
110.         case zt: ZonedDateTime => DateTimeUtils.instantToMicros(zt.toInstant)
111.         case dt: LocalDateTime => DateTimeUtils.instantToMicros(dt.toInstant(ZoneOffset.UTC))
112.         case d: LocalDate => d.toEpochDay.toInt
113.         case lt: LocalTime => {
114.           InternalRow.fromSeq(Seq(
115.             UTF8String.fromString(SchemaService.TIME_TYPE_LOCAL),
116.             UTF8String.fromString(lt.format(DateTimeFormatter.ISO_TIME))
117.           ))
118.         }
119.         case t: OffsetTime => {
120.           InternalRow.fromSeq(Seq(
121.             UTF8String.fromString(SchemaService.TIME_TYPE_OFFSET),
122.             UTF8String.fromString(t.format(DateTimeFormatter.ISO_TIME))
123.           ))
124.         }
125.         case p: InternalPoint2D => {
126.           val srid: Integer = p.srid()
127.           InternalRow.fromSeq(Seq(UTF8String.fromString(SchemaService.POINT_TYPE_2D), srid, p.x(), p.y(), null))
128.         }
129.         case p: InternalPoint3D => {
130.           val srid: Integer = p.srid()
131.           InternalRow.fromSeq(Seq(UTF8String.fromString(SchemaService.POINT_TYPE_3D), srid, p.x(), p.y(), p.z()))
132.         }
133.         case l: java.util.List[_] => {
134.           val elementType = if (schema != null) schema.asInstanceOf[ArrayType].elementType else null
135.           ArrayData.toArrayData(l.asScala.map(e => convertFromNeo4j(e, elementType)).toArray)
136.         }
137.         case map: java.util.Map[_, _] => {
138.           if (schema != null) {
139.             val mapType = schema.asInstanceOf[MapType]
140.             ArrayBasedMapData(map.asScala.map(t => (convertFromNeo4j(t._1, mapType.keyType), convertFromNeo4j(t._2, mapType.valueType))))
141.           } else {
142.             ArrayBasedMapData(map.asScala.map(t => (convertFromNeo4j(t._1), convertFromNeo4j(t._2))))
143.           }
144.         }
145.         case s: String => UTF8String.fromString(s)
146.         case _ => value
147.       }
148.     }
149.   }
150. 
151.   private def extractStructType(dataType: DataType): StructType = dataType match {
152.     case structType: StructType => structType
153.     case mapType: MapType => extractStructType(mapType.valueType)
154.     case arrayType: ArrayType => extractStructType(arrayType.elementType)
155.     case _ => throw new UnsupportedOperationException(s"$dataType not supported")
156.   }
157. 
158.   def convertFromSpark(value: Any, dataType: DataType = null): Value = value match {
159.     case date: java.sql.Date => convertFromSpark(date.toLocalDate, dataType)
160.     case timestamp: java.sql.Timestamp => convertFromSpark(timestamp.toLocalDateTime, dataType)
161.     case intValue: Int if dataType == DataTypes.DateType => convertFromSpark(DateTimeUtils
162.       .toJavaDate(intValue), dataType)
163.     case longValue: Long if dataType == DataTypes.TimestampType => convertFromSpark(DateTimeUtils
164.       .toJavaTimestamp(longValue), dataType)
165.     case unsafeRow: UnsafeRow => {
166.       val structType = extractStructType(dataType)
167.       val row = new GenericRowWithSchema(unsafeRow.toSeq(structType).toArray, structType)
168.       convertFromSpark(row)
169.     }
170.     case struct: GenericRowWithSchema => {
171.       def toMap(struct: GenericRowWithSchema): Value = {
172.         Values.value(
173.           struct.schema.fields.map(
174.             f => f.name -> Neo4jUtil.convertFromSpark(struct.getAs(f.name), f.dataType)
175.           ).toMap.asJava)
176.       }
177. 
178.       try {
179.         struct.getAs[UTF8String]("type").toString match {
180.           case SchemaService.POINT_TYPE_2D => Values.point(struct.getAs[Number]("srid").intValue(),
181.             struct.getAs[Number]("x").doubleValue(),
182.             struct.getAs[Number]("y").doubleValue())
183.           case SchemaService.POINT_TYPE_3D => Values.point(struct.getAs[Number]("srid").intValue(),
184.             struct.getAs[Number]("x").doubleValue(),
185.             struct.getAs[Number]("y").doubleValue(),
186.             struct.getAs[Number]("z").doubleValue())
187.           case SchemaService.DURATION_TYPE => Values.isoDuration(struct.getAs[Number]("months").longValue(),
188.             struct.getAs[Number]("days").longValue(),
189.             struct.getAs[Number]("seconds").longValue(),
190.             struct.getAs[Number]("nanoseconds").intValue())
191.           case SchemaService.TIME_TYPE_OFFSET => Values.value(OffsetTime.parse(struct.getAs[UTF8String]("value").toString))
192.           case SchemaService.TIME_TYPE_LOCAL => Values.value(LocalTime.parse(struct.getAs[UTF8String]("value").toString))
193.           case _ => toMap(struct)
194.         }
195.       } catch {
196.         case _: Throwable => toMap(struct)
197.       }
198.     }
199.     case unsafeArray: UnsafeArrayData => {
200.       val sparkType = dataType match {
201.         case arrayType: ArrayType => arrayType.elementType
202.         case _ => dataType
203.       }
204.       val javaList = unsafeArray.toSeq[AnyRef](sparkType)
205.         .map(elem => convertFromSpark(elem, sparkType))
206.         .asJava
207.       Values.value(javaList)
208.     }
209.     case unsafeMapData: UnsafeMapData => { // Neo4j only supports Map[String, AnyRef]
210.       val mapType = dataType.asInstanceOf[MapType]
211.       val map: Map[String, AnyRef] = (0 until unsafeMapData.numElements())
212.         .map(i => (unsafeMapData.keyArray().getUTF8String(i).toString, unsafeMapData.valueArray().get(i, mapType.valueType)))
213.         .toMap[String, AnyRef]
214.         .mapValues(innerValue => convertFromSpark(innerValue, mapType.valueType))
215.         .toMap[String, AnyRef]
216.       Values.value(map.asJava)
217.     }
218.     case string: UTF8String => convertFromSpark(string.toString)
219.     case _ => Values.value(value)
220.   }
221. 
222.   def isLong(str: String): Boolean = {
223.     if (str == null) {
224.       false
225.     } else {
226.       try {
227.         str.trim.toLong
228.         true
229.       } catch {
230.         case nfe: NumberFormatException => false
231.         case t: Throwable => throw t
232.       }
233.     }
234.   }
235. 
236.   def connectorVersion: String = properties.getOrDefault("version", "UNKNOWN").toString
237. 
238.   def getCorrectProperty(container: PropertyContainer, attribute: String): Property = {
239.     container.property(attribute.split('.'): _*)
240.   }
241. 
242.   def paramsFromFilters(filters: Array[Filter]): Map[String, Any] = {
243.     filters.flatMap(f => f.flattenFilters).map(_.getAttributeAndValue)
244.       .filter(_.nonEmpty)
245.       .map(valAndAtt => valAndAtt.head.toString.unquote() -> toParamValue(valAndAtt(1)))
246.       .toMap
247.   }
248. 
249.   def toParamValue(value: Any): Any = {
250.     value match {
251.       case date: java.sql.Date => date.toString
252.       case timestamp: java.sql.Timestamp => timestamp.toLocalDateTime
253.       case _ => value
254.     }
255.   }
256. 
257.   def valueToCypherExpression(attribute: String, value: Any): Expression = {
258.     val parameter = Cypher.parameter(attribute.toParameterName(value))
259.     value match {
260.       case d: java.sql.Date => Functions.date(parameter)
261.       case t: java.sql.Timestamp => Functions.localdatetime(parameter)
262.       case _ => parameter
263.     }
264.   }
265. 
266.   def mapSparkFiltersToCypher(filter: Filter, container: PropertyContainer, attributeAlias: Option[String] = None): Condition = {
267.     filter match {
268.       case eqns: EqualNullSafe =>
269.         val parameter = valueToCypherExpression(eqns.attribute, eqns.value)
270.         val property = getCorrectProperty(container, attributeAlias.getOrElse(eqns.attribute))
271.         property.isNull.and(parameter.isNull)
272.           .or(
273.             property.isEqualTo(parameter)
274.           )
275.       case eq: EqualTo =>
276.         getCorrectProperty(container, attributeAlias.getOrElse(eq.attribute))
277.           .isEqualTo(valueToCypherExpression(eq.attribute, eq.value))
278.       case gt: GreaterThan =>
279.         getCorrectProperty(container, attributeAlias.getOrElse(gt.attribute))
280.           .gt(valueToCypherExpression(gt.attribute, gt.value))
281.       case gte: GreaterThanOrEqual =>
282.         getCorrectProperty(container, attributeAlias.getOrElse(gte.attribute))
283.           .gte(valueToCypherExpression(gte.attribute, gte.value))
284.       case lt: LessThan =>
285.         getCorrectProperty(container, attributeAlias.getOrElse(lt.attribute))
286.           .lt(valueToCypherExpression(lt.attribute, lt.value))
287.       case lte: LessThanOrEqual =>
288.         getCorrectProperty(container, attributeAlias.getOrElse(lte.attribute))
289.           .lte(valueToCypherExpression(lte.attribute, lte.value))
290.       case in: In =>
291.         getCorrectProperty(container, attributeAlias.getOrElse(in.attribute))
292.           .in(valueToCypherExpression(in.attribute, in.values))
293.       case startWith: StringStartsWith =>
294.         getCorrectProperty(container, attributeAlias.getOrElse(startWith.attribute))
295.           .startsWith(valueToCypherExpression(startWith.attribute, startWith.value))
296.       case endsWith: StringEndsWith =>
297.         getCorrectProperty(container, attributeAlias.getOrElse(endsWith.attribute))
298.           .endsWith(valueToCypherExpression(endsWith.attribute, endsWith.value))
299.       case contains: StringContains =>
300.         getCorrectProperty(container, attributeAlias.getOrElse(contains.attribute))
301.           .contains(valueToCypherExpression(contains.attribute, contains.value))
302.       case notNull: IsNotNull => getCorrectProperty(container, attributeAlias.getOrElse(notNull.attribute)).isNotNull
303.       case isNull: IsNull => getCorrectProperty(container, attributeAlias.getOrElse(isNull.attribute)).isNull
304.       case not: Not => mapSparkFiltersToCypher(not.child, container, attributeAlias).not()
305.       case filter@(_: Filter) => throw new IllegalArgumentException(s"Filter of type `$filter` is not supported.")
306.     }
307.   }
308. 
309.   def getStreamingPropertyName(options: Neo4jOptions) = options.query.queryType match {
310.     case QueryType.RELATIONSHIP => s"rel.${options.streamingOptions.propertyName}"
311.     case _ => options.streamingOptions.propertyName
312.   }
313. 
314.   def callSchemaService[T](neo4jOptions: Neo4jOptions,
315.                            jobId: String,
316.                            filters: Array[Filter],
317.                            function: SchemaService => T): T = {
318.     val driverCache = new DriverCache(neo4jOptions.connection, jobId)
319.     val schemaService = new SchemaService(neo4jOptions, driverCache, filters)
320.     var hasError = false
321.     try {
322.       function(schemaService)
323.     } catch {
324.       case e: Throwable => {
325.         hasError = true
326.         throw e
327.       }
328.     } finally {
329.       schemaService.close()
330.       if (hasError) {
331.         driverCache.close()
332.       }
333.     }
334.   }
335. 
336.   def isRetryableException(neo4jTransientException: Neo4jException) = (neo4jTransientException.isInstanceOf[SessionExpiredException]
337.     || neo4jTransientException.isInstanceOf[TransientException]
338.     || neo4jTransientException.isInstanceOf[ServiceUnavailableException])
339. }
340.

