101. class Neo4jQueryReadStrategy(filters: Array[Filter] = Array.empty[Filter],
102.                              partitionSkipLimit: PartitionSkipLimit = PartitionSkipLimit.EMPTY,
103.                              requiredColumns: Seq[String] = Seq.empty,
104.                              aggregateColumns: Array[AggregateFunc] = Array.empty) extends Neo4jQueryStrategy {
105.   private val renderer: Renderer = Renderer.getDefaultRenderer
106. 
107.   private val hasPartitons: Boolean = partitionSkipLimit.skip != -1 && partitionSkipLimit.limit != -1
108. 
109.   override def createStatementForQuery(options: Neo4jOptions): String = {
110.     val limitedQuery = if (hasPartitons) {
111.       s"""${options.query.value}
112.          |SKIP ${partitionSkipLimit.skip} LIMIT ${partitionSkipLimit.limit}
113.          |""".stripMargin
114.     } else {
115.       options.query.value
116.     }
117.     s"""WITH ${"$"}scriptResult AS ${Neo4jQueryStrategy.VARIABLE_SCRIPT_RESULT}
118.        |$limitedQuery""".stripMargin
119.   }
120. 
121.   override def createStatementForRelationships(options: Neo4jOptions): String = {
122.     val sourceNode = createNode(Neo4jUtil.RELATIONSHIP_SOURCE_ALIAS, options.relationshipMetadata.source.labels)
123.     val targetNode = createNode(Neo4jUtil.RELATIONSHIP_TARGET_ALIAS, options.relationshipMetadata.target.labels)
124. 
125.     val relationship = sourceNode.relationshipTo(targetNode, options.relationshipMetadata.relationshipType)
126.       .named(Neo4jUtil.RELATIONSHIP_ALIAS)
127. 
128.     val matchQuery: StatementBuilder.OngoingReadingWithoutWhere = filterRelationship(sourceNode, targetNode, relationship)
129. 
130.     val returnExpressions: Seq[Expression] = buildReturnExpression(sourceNode, targetNode, relationship)
131.     val stmt = if (aggregateColumns.isEmpty) {
132.       buildStatement(options, matchQuery.returning(returnExpressions : _*), relationship)
133.     } else {
134.       buildStatementAggregation(options, matchQuery, relationship, returnExpressions)
135.     }
136.     renderer.render(stmt)
137.   }
138. 
139.   private def buildReturnExpression(sourceNode: Node, targetNode: Node, relationship: Relationship): Seq[Expression] = {
140.     if (requiredColumns.isEmpty) {
141.       Seq(relationship.getRequiredSymbolicName, sourceNode.as(Neo4jUtil.RELATIONSHIP_SOURCE_ALIAS), targetNode.as(Neo4jUtil.RELATIONSHIP_TARGET_ALIAS))
142.     }
143.     else {
144.       requiredColumns.map(column => {
145.         val splatColumn = column.split('.')
146.         val entityName = splatColumn.head
147. 
148.         val entity = if (entityName.contains(Neo4jUtil.RELATIONSHIP_ALIAS)) {
149.           relationship
150.         }
151.         else if (entityName.contains(Neo4jUtil.RELATIONSHIP_SOURCE_ALIAS)) {
152.           sourceNode
153.         }
154.         else if (entityName.contains(Neo4jUtil.RELATIONSHIP_TARGET_ALIAS)) {
155.           targetNode
156.         }
157.         else {
158.           null
159.         }
160. 
161.         if (entity != null && splatColumn.length == 1) {
162.           entity match {
163.             case n: Node => n.as(entityName.quote())
164.             case r: Relationship => r.getRequiredSymbolicName
165.           }
166.         }
167.         else {
168.           getCorrectProperty(column, entity)
169.         }
170.       })
171.     }
172.   }
173. 
174.   private def buildStatementAggregation(options: Neo4jOptions,
175.                                         query: StatementBuilder.OngoingReadingWithoutWhere,
176.                                         entity: PropertyContainer,
177.                                         fields: Seq[Expression]) = {
178.     val ret: StatementBuilder.BuildableStatement = if (hasPartitons) {
179.       val id = entity match {
180.         case node: Node => Functions.id(node)
181.         case rel: Relationship => Functions.id(rel)
182.       }
183.       query
184.         .`with`(entity)
185.         .orderBy(id)
186.         .skip(partitionSkipLimit.skip)
187.         .asInstanceOf[StatementBuilder.ExposesLimit with StatementBuilder.OngoingReadingAndWith]
188.         .limit(partitionSkipLimit.limit)
189.         .returning(fields: _*)
190.     } else {
191.       val orderByProp = options.orderBy
192.       if (StringUtils.isBlank(orderByProp)) {
193.         query.returning(fields: _*)
194.       } else {
195.         val order: StatementBuilder.OngoingReadingAndWithWithWhereAndOrder = query.`with`(entity).orderBy(entity.property(orderByProp))
196.           .asInstanceOf[StatementBuilder.OngoingOrderDefinition]
197.           .ascending()
198.         order
199.           .returning(fields: _*)
200.           .asInstanceOf[StatementBuilder.BuildableStatement]
201.       }
202.     }
203.     ret.build()
204.   }
205. 
206.   private def buildStatement(options: Neo4jOptions,
207.                              returning: StatementBuilder.OngoingReadingAndReturn,
208.                              entity: PropertyContainer = null) = {
209. 
210.     def addSkipLimit(ret: StatementBuilder.TerminalExposesSkip
211.         with StatementBuilder.TerminalExposesLimit
212.         with StatementBuilder.BuildableStatement) = ret
213.       .skip(partitionSkipLimit.skip).asInstanceOf[StatementBuilder.TerminalExposesLimit].limit(partitionSkipLimit.limit)
214. 
215.     val ret = if (entity == null) {
216.       if (hasPartitons) addSkipLimit(returning) else returning
217.     } else {
218.       if (hasPartitons) {
219.         val id = entity match {
220.           case node: Node => Functions.id(node)
221.           case rel: Relationship => Functions.id(rel)
222.         }
223.         addSkipLimit(returning.orderBy(id))
224.       } else {
225.         val orderByProp = options.orderBy
226.         if (StringUtils.isBlank(orderByProp)) returning else returning.orderBy(entity.property(orderByProp))
227.       }
228.     }
229.     ret.build()
230.   }
231. 
232.   private def filterRelationship(sourceNode: Node, targetNode: Node, relationship: Relationship) = {
233.     val matchQuery = Cypher.`match`(sourceNode).`match`(targetNode).`match`(relationship)
234. 
235.     def getContainer(filter: Filter): PropertyContainer = {
236.       if (filter.isAttribute(Neo4jUtil.RELATIONSHIP_SOURCE_ALIAS)) {
237.         sourceNode
238.       }
239.       else if (filter.isAttribute(Neo4jUtil.RELATIONSHIP_TARGET_ALIAS)) {
240.         targetNode
241.       }
242.       else if (filter.isAttribute(Neo4jUtil.RELATIONSHIP_ALIAS)) {
243.         relationship
244.       }
245.       else {
246.         throw new IllegalArgumentException(s"Attribute '${filter.getAttribute.get}' is not valid")
247.       }
248.     }
249. 
250.     if (filters.nonEmpty) {
251.       def mapFilter(filter: Filter): Condition = {
252.         filter match {
253.           case and: And => mapFilter(and.left).and(mapFilter(and.right))
254.           case or: Or => mapFilter(or.left).or(mapFilter(or.right))
255.           case filter: Filter => Neo4jUtil.mapSparkFiltersToCypher(filter, getContainer(filter), filter.getAttributeWithoutEntityName)
256.         }
257.       }
258. 
259.       val cypherFilters = filters.map(mapFilter)
260. 
261.       assembleConditionQuery(matchQuery, cypherFilters)
262.     }
263.     matchQuery
264.   }
265. 
266.   private def getCorrectProperty(column: String, entity: PropertyContainer): Expression = {
267.     column match {
268.       case Neo4jUtil.INTERNAL_ID_FIELD => Functions.id(entity.asInstanceOf[Node]).as(Neo4jUtil.INTERNAL_ID_FIELD)
269.       case Neo4jUtil.INTERNAL_REL_ID_FIELD => Functions.id(entity.asInstanceOf[Relationship]).as(Neo4jUtil.INTERNAL_REL_ID_FIELD)
270.       case Neo4jUtil.INTERNAL_REL_SOURCE_ID_FIELD => Functions.id(entity.asInstanceOf[Node]).as(Neo4jUtil.INTERNAL_REL_SOURCE_ID_FIELD)
271.       case Neo4jUtil.INTERNAL_REL_TARGET_ID_FIELD => Functions.id(entity.asInstanceOf[Node]).as(Neo4jUtil.INTERNAL_REL_TARGET_ID_FIELD)
272.       case Neo4jUtil.INTERNAL_REL_TYPE_FIELD => Functions.`type`(entity.asInstanceOf[Relationship]).as(Neo4jUtil.INTERNAL_REL_TYPE_FIELD)
273.       case Neo4jUtil.INTERNAL_LABELS_FIELD => Functions.labels(entity.asInstanceOf[Node]).as(Neo4jUtil.INTERNAL_LABELS_FIELD)
274.       case Neo4jUtil.INTERNAL_REL_SOURCE_LABELS_FIELD => Functions.labels(entity.asInstanceOf[Node]).as(Neo4jUtil.INTERNAL_REL_SOURCE_LABELS_FIELD)
275.       case Neo4jUtil.INTERNAL_REL_TARGET_LABELS_FIELD => Functions.labels(entity.asInstanceOf[Node]).as(Neo4jUtil.INTERNAL_REL_TARGET_LABELS_FIELD)
276.       case "*" => Asterisk.INSTANCE
277.       case name => {
278.         val cleanedName = name.removeAlias()
279.         aggregateColumns
280.           .filter(_.toString == name)
281.           .headOption
282.           .map(ag => ag match {
283.             case count: Count => {
284.               val prop = entity.property(count.column().describe().unquote().removeAlias())
285.               if (count.isDistinct) {
286.                 Functions.countDistinct(prop).as(name)
287.               } else {
288.                 Functions.count(prop).as(name)
289.               }
290.             }
291.             case countStar: CountStar => Functions.count(Asterisk.INSTANCE).as(name)
292.             case max: Max => Functions.max(entity.property(max.column().describe().unquote().removeAlias())).as(name)
293.             case min: Min => Functions.min(entity.property(min.column().describe().unquote().removeAlias())).as(name)
294.             case sum: Sum => {
295.               val prop = entity.property(sum.column().describe().unquote().removeAlias())
296.               if (sum.isDistinct) {
297.                 Functions.sumDistinct(prop).as(name)
298.               } else {
299.                 Functions.sum(prop).as(name)
300.               }
301.             }
302.           })
303.           .getOrElse(entity.property(cleanedName).as(name))
304.           .asInstanceOf[Expression]
305.       }
306.     }
307.   }
308. 
309.   override def createStatementForNodes(options: Neo4jOptions): String = {
310.     val node = createNode(Neo4jUtil.NODE_ALIAS, options.nodeMetadata.labels)
311.     val matchQuery = filterNode(node)
312.     val expressions = requiredColumns.map(column => getCorrectProperty(column, node))
313.     val stmt = if (aggregateColumns.nonEmpty) {
314.       buildStatementAggregation(options, matchQuery, node, expressions)
315.     } else {
316.       val ret = if (requiredColumns.isEmpty) {
317.         matchQuery.returning(node)
318.       } else {
319.         matchQuery.returning(expressions : _*)
320.       }
321.       buildStatement(options, ret, node)
322.     }
323.     renderer.render(stmt)
324.   }
