314.   def callSchemaService[T](neo4jOptions: Neo4jOptions,
315.                            jobId: String,
316.                            filters: Array[Filter],
317.                            function: SchemaService => T): T = {
318.     val driverCache = new DriverCache(neo4jOptions.connection, jobId)
319.     val schemaService = new SchemaService(neo4jOptions, driverCache, filters)
320.     var hasError = false
321.     try {
322.       function(schemaService)
323.     } catch {
324.       case e: Throwable => {
325.         hasError = true
326.         throw e
327.       }
328.     } finally {
329.       schemaService.close()
330.       if (hasError) {
331.         driverCache.close()
332.       }
333.     }
334.   }
