37.   private def createQueryPart(keyword: String, labels: String, keys: String, alias: String): String = {
38.     val setStatement = if (!keyword.equals("MATCH")) s" SET $alias += ${Neo4jQueryStrategy.VARIABLE_EVENT}.$alias.${Neo4jWriteMappingStrategy.PROPERTIES}" else ""
39.     s"""$keyword ($alias${if (labels.isEmpty) "" else s":$labels"} ${if (keys.isEmpty) "" else s"{$keys}"})$setStatement""".stripMargin
40.   }
41. 
42.   override def createStatementForRelationships(options: Neo4jOptions): String = {
43.     val relationshipKeyword = keywordFromSaveMode(saveMode)
44.     val sourceKeyword = keywordFromSaveMode(options.relationshipMetadata.sourceSaveMode)
45.     val targetKeyword = keywordFromSaveMode(options.relationshipMetadata.targetSaveMode)
46. 
47.     val relationship = options.relationshipMetadata.relationshipType.quote()
48. 
49.     val sourceLabels = options.relationshipMetadata.source.labels
50.       .map(_.quote())
51.       .mkString(":")
52. 
53.     val targetLabels = options.relationshipMetadata.target.labels
54.       .map(_.quote())
55.       .mkString(":")
56. 
57.     val sourceKeys = createPropsList(
58.       options.relationshipMetadata.source.nodeKeys,
59.       s"source.${Neo4jWriteMappingStrategy.KEYS}"
60.     )
61.     val targetKeys = createPropsList(
62.       options.relationshipMetadata.target.nodeKeys,
63.       s"target.${Neo4jWriteMappingStrategy.KEYS}"
64.     )
65.     val sourceQueryPart = createQueryPart(sourceKeyword, sourceLabels, sourceKeys, Neo4jUtil.RELATIONSHIP_SOURCE_ALIAS)
66.     val targetQueryPart = createQueryPart(targetKeyword, targetLabels, targetKeys, Neo4jUtil.RELATIONSHIP_TARGET_ALIAS)
67. 
68.     val withQueryPart = if (sourceKeyword != "MATCH" && targetKeyword == "MATCH")
69.       "\nWITH source, event"
70.     else {
71.       ""
72.     }
73. 
74.     s"""UNWIND ${"$"}events AS ${Neo4jQueryStrategy.VARIABLE_EVENT}
75.        |$sourceQueryPart$withQueryPart
76.        |$targetQueryPart
77.        |$relationshipKeyword (${Neo4jUtil.RELATIONSHIP_SOURCE_ALIAS})-[${Neo4jUtil.RELATIONSHIP_ALIAS}:$relationship]->(${Neo4jUtil.RELATIONSHIP_TARGET_ALIAS})
78.        |SET ${Neo4jUtil.RELATIONSHIP_ALIAS} += ${Neo4jQueryStrategy.VARIABLE_EVENT}.${Neo4jUtil.RELATIONSHIP_ALIAS}.${Neo4jWriteMappingStrategy.PROPERTIES}
79.        |""".stripMargin
80.   }
81. 
82.   override def createStatementForNodes(options: Neo4jOptions): String = {
83.     val keyword = keywordFromSaveMode(saveMode)
84. 
85.     val labels = options.nodeMetadata.labels
86.       .map(_.quote())
87.       .mkString(":")
88. 
89.     val keys = createPropsList(
90.       options.nodeMetadata.nodeKeys,
91.       Neo4jWriteMappingStrategy.KEYS
92.     )
93. 
94.     s"""UNWIND ${"$"}events AS ${Neo4jQueryStrategy.VARIABLE_EVENT}
95.        |$keyword (node${if (labels.isEmpty) "" else s":$labels"} ${if (keys.isEmpty) "" else s"{$keys}"})
96.        |SET node += ${Neo4jQueryStrategy.VARIABLE_EVENT}.${Neo4jWriteMappingStrategy.PROPERTIES}
97.        |""".stripMargin
98.   }
99. }
